package com.manas.mergegate.security;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Runs the full 60-case seeded security corpus (committed at
 * src/main/resources/security/security_corpus.json, generated by
 * scripts/generate_security_corpus.py) through the real SecurityGate and checks the measured
 * false-positive and missed counts directly, the same numbers SecurityGateMain writes to
 * security_gate_results.json and the README reports.
 */
class SecurityGateCorpusTest {

    @Test
    void theSeededSecurityCorpusHasZeroFalsePositivesAndZeroMissedCases() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        List<SecurityCase> cases = mapper.readValue(
                getClass().getResourceAsStream("/security/security_corpus.json"),
                mapper.getTypeFactory().constructCollectionType(List.class, SecurityCase.class));
        assertEquals(60, cases.size());

        SecurityGate gate = new SecurityGate();
        List<SecurityCaseResult> results = gate.evaluateAll(cases);

        long falsePositives = results.stream().filter(SecurityCaseResult::falsePositive).count();
        long missed = results.stream().filter(SecurityCaseResult::missed).count();

        assertEquals(0, falsePositives, "false positives: " + results);
        assertEquals(0, missed, "missed: " + results);
    }
}
